const DeliveriesAdmin=(()=>{const $=id=>document.getElementById(id);async function load(){$("dlv-status").innerHTML=loadingMessageHtml();const res=await Api.post("adminListDeliveries",{token:Auth.getToken(),status:$("dlv-filter").value});if(!res.ok||!res.counts){$("dlv-status").textContent=res&&res.error||"Could not load deliveries.";return}$("dlv-status").textContent="";$("dlv-mode").textContent=res.enabled?res.allIslands?"Mwakete drivers are ON on every island. A job is only for a store and buyer on the same island, and only drivers there see it.":`Mwakete drivers are ON for: ${res.areas.join(", ")} (within one island only).`:"Mwakete drivers are OFF (Script Property DELIVERY_JOBS). Nothing here is visible to sellers or drivers yet.";const c=res.counts;const card=(label,v,sub)=>`<div class="kpi-card"><span class="kpi-label">${escapeHtml(label)}</span><strong class="kpi-value">${v}</strong>${sub?`<span class="kpi-sub${/stuck|fail/i.test(sub)&&v?" is-warning":""}">${escapeHtml(sub)}</span>`:""}</div>`;$("dlv-counts").innerHTML=card("Waiting for a driver",c.open,"")+card("On the way",c.active,"")+card("Failed / stuck",c.failed+c.stuck,`${c.failed} failed · ${c.stuck} stuck`)+card("Drivers online",c.driversOnline,`${c.driversPending} waiting for approval`)+card("Payments to check",c.paymentsToCheck,`${c.refundsDue} refund${c.refundsDue===1?"":"s"} due · ${c.toDecide} to decide`);$("dlv-bank").textContent=res.bankDetailsSet?"":"Mwakete’s bank details are not set (Script Property MWAKETE_BANK_DETAILS), so sellers cannot pay for wallet deliveries yet.";loadPayouts();$("dlv-drivers").innerHTML=res.drivers.length?`<table class="dash-table"><thead><tr><th scope="col">Driver</th><th scope="col">Vehicle / area</th><th scope="col">Record</th><th scope="col">Status</th></tr></thead><tbody>${res.drivers.map(d=>`<tr>\n      <td data-label="Driver">${escapeHtml(d.name)}<span class="dash-table-sub"><a href="tel:${escapeHtml(d.phone)}">${escapeHtml(d.phone)}</a> · ${escapeHtml(d.email)}</span>${driverDocsCell(d)}</td>\n      <td data-label="Vehicle / area">${escapeHtml(d.vehicle)}<span class="dash-table-sub">${escapeHtml(d.area)}</span></td>\n      <td data-label="Record">${d.delivered} delivered · ${d.failed} failed</td>\n      <td data-label="Status"><strong>${escapeHtml(d.status)}</strong>${d.online?" · online":""}${d.note?`<span class="dash-table-sub">${escapeHtml(d.note)}</span>`:""}\n        <span class="dlv-actions">${d.status!=="approved"?`<button type="button" class="btn btn-small" data-driver="${escapeHtml(d.driverId)}" data-set="approved">Approve</button>`:""}\n        ${d.status==="pending"?`<button type="button" class="btn btn-small" data-driver="${escapeHtml(d.driverId)}" data-set="rejected">Reject</button>`:""}\n        ${d.status==="approved"?`<button type="button" class="btn btn-small" data-driver="${escapeHtml(d.driverId)}" data-set="suspended">Suspend</button>`:""}</span></td></tr>`).join("")}</tbody></table>`:'<p class="dash-empty">No driver applications yet.</p>';$("dlv-jobs").innerHTML=res.jobs.length?`<table class="dash-table"><thead><tr><th scope="col">Order</th><th scope="col">Driver</th><th scope="col">Fee</th><th scope="col">Status</th></tr></thead><tbody>${res.jobs.map(j=>`<tr>\n      <td data-label="Order"><a href="../order-room.html?order=${encodeURIComponent(j.orderId)}&amp;as=admin">${escapeHtml(j.orderId)}</a><span class="dash-table-sub">${escapeHtml(j.storeName)} → ${escapeHtml(j.dropoff)}</span></td>\n      <td data-label="Driver">${j.driverName?`${escapeHtml(j.driverName)}<span class="dash-table-sub"><a href="tel:${escapeHtml(j.driverPhone)}">${escapeHtml(j.driverPhone)}</a></span>`:"—"}\n        ${j.location?`<span class="dash-table-sub"><a href="${escapeHtml(j.location.link)}" target="_blank" rel="noopener">Live location</a></span>`:""}</td>\n      <td data-label="Fee">${formatMoney(j.fee)}<span class="dash-table-sub">${j.payStatus?escapeHtml(j.payLabel):j.feePaid?"Paid":"Not marked paid"}</span>\n        ${j.payStatus==="submitted"||j.payStatus==="rejected"?`<span class="dash-table-sub">Reference <strong>${escapeHtml(j.payRef)}</strong> · bank ref ${escapeHtml(j.payBankRef)} · ${j.payAmount==null?"":formatMoney(j.payAmount)}</span>`:""}\n        ${j.payNote?`<span class="dash-table-sub">${escapeHtml(j.payNote)}</span>`:""}\n        ${j.payStatus==="submitted"?`<span class="dlv-actions"><button type="button" class="btn btn-small" data-pay="confirm" data-job="${escapeHtml(j.jobId)}" data-fee="${escapeHtml(j.fee)}">Confirm received</button>\n          <button type="button" class="btn btn-small" data-pay="reject" data-job="${escapeHtml(j.jobId)}">Not received</button></span>`:""}\n        ${j.payStatus==="review"?`<span class="dlv-actions"><button type="button" class="btn btn-small" data-pay="decide" data-job="${escapeHtml(j.jobId)}">Decide who is paid</button></span>`:""}\n        ${j.payStatus==="refund_due"?`<span class="dlv-actions"><button type="button" class="btn btn-small" data-pay="refund" data-job="${escapeHtml(j.jobId)}">I sent the refund</button></span>`:""}</td>\n      <td data-label="Status">${escapeHtml(j.statusLabel)}${j.stuck?' <span class="status-badge status-problem">Stuck</span>':""}${j.failReason?`<span class="dash-table-sub">${escapeHtml(j.failReason)}</span>`:""}</td></tr>`).join("")}</tbody></table>`:'<p class="dash-empty">No delivery jobs here.</p>'}async function loadPayouts(){const res=await Api.post("adminListPayouts",{token:Auth.getToken()});if(!res.ok||!res.holding){$("dlv-payouts").innerHTML="";$("dlv-holding").innerHTML="";return}const h=res.holding,money=v=>formatMoney(v);const card=(label,v,sub)=>`<div class="kpi-card"><span class="kpi-label">${escapeHtml(label)}</span><strong class="kpi-value">${money(v)}</strong>${sub?`<span class="kpi-sub">${escapeHtml(sub)}</span>`:""}</div>`;$("dlv-holding").innerHTML=card("Mwakete should hold",h.total,"in total, for sellers and drivers")+card("Delivery fees in progress",h.heldForOpenJobs+h.awaitingDecision,"paid by sellers, not yet credited")+card("Owed to drivers",h.owedToDrivers,"credited, not yet claimed")+card("Claims to pay",h.claimsToPay,"drivers waiting for a transfer")+card("Refunds due to sellers",h.refundsDue,"");const claims=res.claims.length?`<table class="dash-table"><thead><tr><th scope="col">Driver</th><th scope="col">Amount</th><th scope="col">Send to</th><th scope="col">Asked</th></tr></thead><tbody>${res.claims.map(c=>`<tr>\n        <td data-label="Driver">${escapeHtml(c.driverName)}<span class="dash-table-sub"><a href="tel:${escapeHtml(c.driverPhone)}">${escapeHtml(c.driverPhone)}</a></span></td>\n        <td data-label="Amount"><strong>${money(c.amount)}</strong></td>\n        <td data-label="Send to">${escapeHtml(c.details)}</td>\n        <td data-label="Asked">${escapeHtml(new Date(c.at).toLocaleDateString())}<span class="dlv-actions"><button type="button" class="btn btn-small" data-payout="paid" data-claim="${escapeHtml(c.claimId)}">I paid it</button>\n          <button type="button" class="btn btn-small" data-payout="reverse" data-claim="${escapeHtml(c.claimId)}">Send back</button></span></td></tr>`).join("")}</tbody></table>`:'<p class="dash-empty">No payout claims waiting.</p>';const bal=res.drivers.length?`<details><summary>Driver balances (${res.drivers.length})</summary><table class="dash-table"><thead><tr><th scope="col">Driver</th><th scope="col">Available</th><th scope="col">In hold</th><th scope="col">Paid out</th></tr></thead><tbody>${res.drivers.map(d=>`<tr>\n        <td data-label="Driver">${escapeHtml(d.name)}<span class="dlv-actions"><button type="button" class="btn btn-small" data-payout="adjust" data-driver-id="${escapeHtml(d.driverId)}">Correct balance</button></span></td>\n        <td data-label="Available">${money(d.available)}</td><td data-label="In hold">${money(d.pending)}</td><td data-label="Paid out">${money(d.paidOut)}</td></tr>`).join("")}</tbody></table></details>`:"";$("dlv-payouts").innerHTML=claims+bal}async function onPayout(b){const kind=b.dataset.payout;let action,payload;if(kind==="paid"){const bankRef=prompt("Bank reference of the transfer you made to the driver:");if(!bankRef)return;action="adminMarkPayoutPaid";payload={claimId:b.dataset.claim,bankRef:bankRef}}else if(kind==="reverse"){const reason=prompt("Why send this claim back to the driver’s balance? (for example, wrong account details)");if(!reason)return;action="adminReversePayout";payload={claimId:b.dataset.claim,reason:reason}}else{const amount=prompt("Correction in dollars (use a minus sign to take money off, for example -5):");if(amount===null||amount==="")return;const reason=prompt("Why? (recorded with your name)");if(!reason)return;action="adminAdjustDriverWallet";payload={driverId:b.dataset.driverId,amount:amount,reason:reason,requestId:"adj"+Date.now().toString(36)+Math.random().toString(36).slice(2,8)}}const busyDone=setButtonBusy(b,"Saving");const res=await Api.post(action,Object.assign({token:Auth.getToken()},payload));if(!res.ok){alert(res.error||"Not saved.");busyDone();return}await load()}async function onPay(b){const jobId=b.dataset.job,kind=b.dataset.pay;let action,payload;if(kind==="confirm"){if(!confirm("Only confirm after you have checked the REAL bank statement (not a screenshot) and the money is in Mwakete’s account. Continue?"))return;const got=prompt("Amount that arrived ($):",b.dataset.fee);if(got===null||got==="")return;action="adminConfirmJobPayment";payload={amountReceived:got,checkedStatement:true}}else if(kind==="reject"){const reason=prompt("What is wrong? (the seller will see it)");if(!reason)return;action="adminRejectJobPayment";payload={reason:reason}}else if(kind==="decide"){const pay=confirm("This delivery failed with damaged goods or another reason.\n\nOK = pay the driver the fee.\nCancel = refund the seller instead.");const note=prompt(pay?"Why is the driver paid?":"Why is the seller refunded?");if(!note)return;action="adminResolveJobPayment";payload={outcome:pay?"pay_driver":"refund_seller",note:note}}else{const bankRef=prompt("Bank reference of the refund you sent:");if(!bankRef)return;action="adminMarkJobRefunded";payload={bankRef:bankRef}}const busyDone=setButtonBusy(b,"Saving");const res=await Api.post(action,Object.assign({token:Auth.getToken(),jobId:jobId},payload));if(!res.ok){alert(res.error||"Not saved.");busyDone();return}await load()}function driverDocsCell(d){const x=d.docs||{};if(!x.idType&&!x.messenger)return"";const face=x.faceResult==="passed"?`<span class="dlv-face is-ok">${escapeHtml(x.faceLabel)}</span>`:`<span class="dlv-face">${escapeHtml(x.faceLabel||"No face check")}</span>`;const signed=x.contractMethod?`Agreement ${escapeHtml(x.contractVersion)} signed ${x.contractMethod==="digital"?"in the app"+(x.contractSignedName?" as “"+escapeHtml(x.contractSignedName)+"”":""):"on paper"}`:"No agreement";return`<span class="dash-table-sub">${escapeHtml(x.idType)} ${escapeHtml(x.idNumber)} · ${face}</span>\n      <span class="dash-table-sub">${signed}</span>\n      <span class="dash-table-sub">${x.messenger?`<a href="${escapeHtml(x.messenger)}" target="_blank" rel="noopener noreferrer">Message on Messenger</a> · `:""}${x.hasDocs?`<button type="button" class="linklike" data-driver-docs="${escapeHtml(d.driverId)}">View ID &amp; photos</button>`:x.docsDeletedAt?"Documents deleted "+escapeHtml(String(x.docsDeletedAt).slice(0,10)):""}</span>\n      <div class="dlv-docs" id="dlv-docs-${escapeHtml(d.driverId)}" hidden></div>`}async function onDocs(btn){const box=$("dlv-docs-"+btn.dataset.driverDocs);if(!box.hidden){box.hidden=true;box.innerHTML="";return}const busyDone=setButtonBusy(btn,"Opening");const res=await Api.post("adminDriverDocs",{token:Auth.getToken(),driverId:btn.dataset.driverDocs});busyDone();if(!res.ok){alert(res.error||"Could not open the documents.");return}const fig=f=>!f?"":f.missing?`<figure><figcaption>${escapeHtml(f.label)} - file missing</figcaption></figure>`:f.mimeType==="application/pdf"?`<figure><a href="${f.dataUrl}" download="signed-page.pdf">${escapeHtml(f.label)} (PDF)</a></figure>`:`<figure><img src="${f.dataUrl}" alt="${escapeHtml(f.label)}"><figcaption>${escapeHtml(f.label)}</figcaption></figure>`;box.innerHTML=`<p class="dash-table-sub">Compare the face photo with the ID before approving. Private - do not share or download.</p>\n      <div class="dlv-docs-grid">${fig(res.id)}${fig(res.selfie)}${res.contract.map(fig).join("")}</div>`;box.hidden=false}async function onClick(e){const docs=e.target.closest("[data-driver-docs]");if(docs){await onDocs(docs);return}const pay=e.target.closest("[data-pay]");if(pay){await onPay(pay);return}const po=e.target.closest("[data-payout]");if(po){await onPayout(po);return}const b=e.target.closest("[data-driver]");if(!b)return;const status=b.dataset.set;let reason="";if(status!=="approved"){reason=prompt(`Reason to ${status==="rejected"?"reject":"suspend"} this driver (they will see it):`)||"";if(!reason)return}else if(!confirm("Approve this driver? Check that the face photo matches the ID first. Then tell them on Messenger."))return;const busyDone=setButtonBusy(b,"Saving");const res=await Api.post("adminSetDriverStatus",{token:Auth.getToken(),driverId:b.dataset.driver,status:status,reason:reason});if(!res.ok){alert(res.error||"Not saved.");busyDone();return}await load()}function init(){if(!$("deliveries"))return;$("dlv-filter").addEventListener("change",load);$("dlv-drivers").addEventListener("click",onClick);$("dlv-jobs").addEventListener("click",onClick);$("dlv-payouts").addEventListener("click",onClick);load()}return{init:init}})();